<?php
require_once dirname(__DIR__,2).'/core/db_connect.php'; require_once dirname(__DIR__,2).'/core/sports_service.php';
if(!check_rate_limit('sports_public_profile',60,60)){http_response_code(429);exit('Too many requests.');}
$identifier=(string)($_GET['profile']??''); if(!preg_match('/^[a-f0-9]{32}$/',$identifier)){http_response_code(404);exit('Player profile not found.');}
$q=$pdo->prepare("SELECT p.public_identifier,p.public_biography,p.public_achievements,p.institution_name_public,p.profile_photo_path,u.name,a.date_of_birth,a.general_estate,a.education_level,m.primary_position,m.assigned_jersey_number,m.joined_at,COALESCE(s.appearances,0) appearances,COALESCE(s.starts,0) starts,COALESCE(s.goals_scored,0) goals,COALESCE(s.assists,0) assists,COALESCE(s.clean_sheets,0) clean_sheets,COALESCE(s.mvp_awards,0) mvp_awards FROM sports_public_profiles p JOIN sports_members m ON m.id=p.sports_member_id AND m.membership_status='active' JOIN sports_applications a ON a.id=m.application_id AND a.status='approved' JOIN users u ON u.id=m.user_id LEFT JOIN sports_stats s ON s.user_id=u.id WHERE p.public_identifier=? AND p.is_published=1 AND p.reviewed_at IS NOT NULL AND a.publication_acknowledged_at IS NOT NULL AND (TIMESTAMPDIFF(YEAR,a.date_of_birth,CURDATE())>=18 OR a.guardian_consent_at IS NOT NULL) LIMIT 1");$q->execute([$identifier]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Player profile not found.');}
$r=$pdo->prepare("SELECT r.role_code FROM sports_role_assignments r JOIN sports_members m ON m.id=r.sports_member_id JOIN sports_public_profiles p ON p.sports_member_id=m.id WHERE p.public_identifier=? AND r.status='active' ORDER BY r.starts_at");$r->execute([$identifier]);$roles=$r->fetchAll(PDO::FETCH_COLUMN);
function player_label(string $v):string{return ucwords(str_replace('_',' ',$v));}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Approved JDM Kenya Sports Ministry player profile."><title><?=escape($p['name'])?> | Sports Ministry</title><link href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.3/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?=BASE_PATH?>/assets/css/sports.css"></head><body><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="<?=BASE_PATH?>/sports.php">Sports Ministry</a></div></nav><main class="container py-5" style="max-width:960px"><article><div class="row g-4 align-items-center"><div class="col-md-4"><?php if($p['profile_photo_path']):?><img src="<?=escape($p['profile_photo_path'])?>" alt="Approved portrait of <?=escape($p['name'])?>" class="img-fluid rounded shadow-sm"><?php else:?><div class="bg-secondary-subtle rounded d-flex align-items-center justify-content-center" style="aspect-ratio:1"><span class="display-1"><?=escape(mb_substr($p['name'],0,1))?></span></div><?php endif?></div><div class="col-md-8"><h1><?=escape($p['name'])?></h1><p class="lead"><?=escape(player_label($p['primary_position']))?><?= $p['assigned_jersey_number']?' · Jersey #'.(int)$p['assigned_jersey_number']:''?></p><dl class="row"><dt class="col-5">Age</dt><dd class="col-7"><?=sports_age($p['date_of_birth'])?> years</dd><dt class="col-5">General area</dt><dd class="col-7"><?=escape($p['general_estate'])?></dd><dt class="col-5">Education</dt><dd class="col-7"><?=escape(player_label($p['education_level']))?></dd><dt class="col-5">Member since</dt><dd class="col-7"><?=escape(date('F Y',strtotime($p['joined_at'])))?></dd></dl><?php foreach($roles as $role):?><span class="badge text-bg-success me-1"><?=escape(player_label($role))?></span><?php endforeach?></div></div><?php if($p['public_biography']):?><section class="mt-5"><h2>Biography</h2><p><?=nl2br(escape($p['public_biography']))?></p></section><?php endif?><?php if($p['public_achievements']):?><section class="mt-4"><h2>Achievements</h2><p><?=nl2br(escape($p['public_achievements']))?></p></section><?php endif?><section class="mt-4"><h2>Player statistics</h2><div class="row g-2"><?php foreach(['appearances','starts','goals','assists','clean_sheets','mvp_awards'] as $stat):?><div class="col-6 col-md-4"><div class="border rounded p-3"><strong class="d-block fs-3"><?=(int)$p[$stat]?></strong><?=escape(player_label($stat))?></div></div><?php endforeach?></div></section></article></main></body></html>
